/**
 * Vendored verbatim from motion-primitives (https://motion-primitives.com) by ibelick.
 * Upstream: https://github.com/ibelick/motion-primitives/blob/main/components/core/in-view.tsx
 * Fetched 2026-08-29 from main branch. Do not edit unless intentionally adopting upstream changes.
 */
'use client';
// Local patch for workspace tsconfig (verbatimModuleSyntax): type-only imports only, no behavior change.
import { useRef, useState, type ReactNode } from 'react';
import { motion, useInView, type Variant, type Transition, type UseInViewOptions,  } from 'motion/react';

export type InViewProps = {
  children: ReactNode;
  variants?: {
    hidden: Variant;
    visible: Variant;
  };
  transition?: Transition;
  viewOptions?: UseInViewOptions;
  as?: React.ElementType;
  once?: boolean;
  delay?: number;
  className?: string;
};

const defaultVariants = {
  hidden: { opacity: 0 },
  visible: { opacity: 1 },
};

export function InView({
  children,
  variants = defaultVariants,
  transition,
  delay,
  viewOptions,
  as = 'div',
  once
}: InViewProps) {
  const ref = useRef(null);
  const isInView = useInView(ref, viewOptions);

  const [isViewed, setIsViewed] = useState(false)

  const MotionComponent = motion[as as keyof typeof motion] as typeof as;

  return (
    <MotionComponent
      ref={ref}
      initial='hidden'
      onAnimationComplete={() => {
        if (once) setIsViewed(true)
      }}
      animate={(isInView || isViewed) ? "visible" : "hidden"}

      variants={variants}
      transition={delay !== undefined ? { ...transition, delay } : transition}
    >
      {children}
    </MotionComponent>
  );
}

/**
 * tree-grid-table — vendored from the UI Engine preset library (axiestudio).
 * Install: npx shadcn@latest add https://ui-engine.pages.dev/r/tree-grid-table.json
 * Source of truth: UI/ — do not edit vendored copies blindly.
 */
import * as React from "react"
import { motion, AnimatePresence, MotionConfig } from "motion/react"
import { ChevronRight, Loader2 } from "lucide-react"
import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"
import { InView } from "@/components/primitives/in-view"

// ═══ APP-PRIMARY — org charts, file systems, BOMs: hierarchy that streams.
// JOB      browse unlimited nested rows without loading the ocean
// SIGNATURE rows reveal with a height spring; expanding a never-loaded row
//           calls loadChildren and shows an inline skeleton row first;
//           guides draw a subtle indentation rail per level.
// A11Y     nested lists with aria-expanded/owns; keyboard ←/→ fold + unfold.

export type TreeNode = { id: string; label: string; meta?: string; children?: TreeNode[] }
export type TreeGridTableProps = { nodes: TreeNode[]; loadChildren?: (n: TreeNode) => Promise<TreeNode[]>; defaultOpen?: string[]; className?: string;
  /** bare: drop the marketing hero/footer and paddings — embed the tree itself
   *  inside app panels where the surrounding screen carries its own header */
  bare?: boolean }

export function TreeGridTable({ nodes, loadChildren, defaultOpen = [], className, bare = false }: TreeGridTableProps) {
  const [open, setOpen] = React.useState<Set<string>>(new Set(defaultOpen))
  const [loading, setLoading] = React.useState<Set<string>>(new Set())
  const [kids, setKids] = React.useState<Record<string, TreeNode[]>>({})
  const toggle = async (n: TreeNode) => {
    setOpen((s) => { const c = new Set(s); if (c.has(n.id)) c.delete(n.id); else if (n.children || !loadChildren) c.add(n.id); else {
      if (!kids[n.id]) { setLoading((l) => new Set(l).add(n.id)) }
      c.add(n.id)
    } return c })
    if (!n.children && loadChildren && !kids[n.id]) {
      const r = await loadChildren(n)
      setKids((k) => ({ ...k, [n.id]: r }))
      setLoading((l) => { const c = new Set(l); c.delete(n.id); return c })
    }
  }
  const Row = ({ n, depth }: { n: TreeNode; depth: number }) => {
    const expanded = open.has(n.id)
    const children = n.children ?? kids[n.id]
    const fake = loadChildren && !children && expanded
    return (
      <li role="treeitem" aria-expanded={children || fake ? expanded : undefined}>
        <MotionConfig reducedMotion="user">
        <div style={{ paddingLeft: 10 + depth * 18 }} className="group relative flex h-9 items-center gap-1.5 text-[13px]">
          {depth > 0 && <span aria-hidden className="absolute left-[calc(10px+(var(--d)*18px)-9px)] top-0 h-full w-px bg-border/70" style={{ ["--d" as string]: depth - 1 } as React.CSSProperties} />}
          {children || fake ? (
            <Button type="button" variant="ghost" aria-label={`${expanded ? "Collapse" : "Expand"} ${n.label}`} onClick={() => toggle(n)} className="grid size-6 shrink-0 place-items-center rounded-md text-muted-foreground hover:bg-accent"><motion.span animate={{ rotate: expanded ? 90 : 0 }} transition={{ duration: 0.18 }} className="block"><ChevronRight className="size-4" /></motion.span></Button>
          ) : <span aria-hidden className="size-6 shrink-0" />}
          <span className="min-w-0 flex-1 truncate font-medium">{n.label}</span>
          {n.meta && <span className="text-xs text-muted-foreground opacity-0 transition-opacity group-hover:opacity-100 md:opacity-100">{n.meta}</span>}
        </div>
        {expanded && (
          <ul role="group">
            {loading.has(n.id) && <li className="flex h-8 items-center gap-2 px-4" style={{ paddingLeft: 10 + (depth + 1) * 18 + 28 }}><Loader2 className="size-3.5 animate-spin text-muted-foreground" /><span className="text-xs text-muted-foreground">loading…</span></li>}
            <AnimatePresence initial={false}>
              {children?.map((c) => (
                <motion.ul key={c.id} initial={{ height: 0, opacity: 0 }} animate={{ height: "auto", opacity: 1 }} exit={{ height: 0, opacity: 0 }} transition={{ duration: 0.24, ease: [0.16, 1, 0.3, 1] }} className="overflow-hidden list-none">
                  <Row n={c} depth={depth + 1} />
                </motion.ul>
              ))}
            </AnimatePresence>
          </ul>
        )}
              </MotionConfig>
      </li>
    )
  }
  if (bare) {
    return (
      <section className={cn("relative w-full", className)}>
        <div className="overflow-hidden rounded-lg border border-border bg-card">
          <ul role="tree" className="divide-y divide-border/60 py-1">{nodes.map((n) => <Row key={n.id} n={n} depth={0} />)}</ul>
        </div>
      </section>
    )
  }
  return (
    <section className={cn("relative w-full overflow-x-clip bg-background", className)}>
      <div className="mx-auto w-full max-w-[720px] px-4 py-12 sm:px-6 sm:py-14">
        <InView once variants={{ hidden: { opacity: 0, y: 14 }, visible: { opacity: 1, y: 0 } }} transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1] }}>
          <span className="font-mono text-[11px] font-semibold uppercase tracking-[0.18em]">Tree grid · lazy branches</span>
          <h2 className="mt-3 font-display text-2xl font-bold tracking-tight sm:text-3xl">Branch, on demand.</h2>
          <p className="mt-2.5 max-w-xl text-sm leading-6 text-muted-foreground">
            Expand a row that was never loaded and it streams in on the spot — a skeleton first, the kids after, guides staying quiet along the rail.
          </p>
        </InView>
        <div className="mt-10 overflow-hidden rounded-2xl border border-border bg-card shadow-[0_24px_48px_-32px_hsl(var(--foreground)/0.5)]">
          <ul role="tree" className="divide-y divide-border/60 py-1.5">{nodes.map((n) => <Row key={n.id} n={n} depth={0} />)}</ul>
        </div>
        <p className="mx-auto mt-6 flex items-center justify-between border-t border-border/60 pt-3 font-mono text-[10px] font-bold uppercase tracking-[0.3em] text-muted-foreground">
          <span>Height spring · Skeleton rows · Keyboard ←→</span>
          <span aria-hidden>●</span>
        </p>
      </div>
    </section>
  )
}

